style.css:
/* Dark Vintage Rose */
body { background: #211719 !important; color: #EBD4D1 !important; }
h1, h2, h3 { color: #D49AA1 !important; }
p { color: #C5A5A3 !important; }
a { color: #D8A0A8 !important; }
button {
  background: #74434C !important;
  color: #F8E7E5 !important;
  border: 1px solid #A96D77 !important;
  border-radius: 6px !important;
}
input, textarea {
  background: #302225 !important;
  color: #EBD4D1 !important;
  border: 1px solid #80545B !important;
}
::selection { background: #A96D77; color: white; }
